def countComponents(n,edges):
    parent=list(range(n))
    def find(x):
        while parent[x]!=x: parent[x]=parent[parent[x]];x=parent[x]
        return x
    def union(x,y):
        rx,ry=find(x),find(y)
        if rx!=ry: parent[ry]=rx
    for u,v in edges: union(u,v)
    return len({find(i) for i in range(n)})

